:0 12px 30px rgba(0,0,0,.1)}.form{display:grid;grid-template-columns:1fr 1fr;gap:8px}.wide{grid-column:1/-1}label{display:block;margin-bottom:4px;font-size:8px;font-weight:900;color:#555c57}.timeline{display:grid}.event{display:grid;grid-template-columns:13px 1fr;gap:8px}.dot{width:8px;height:8px;margin-top:10px;border-radius:50%;background:var(--accent)}.eventbody{padding:7px 0 11px;border-bottom:1px solid var(--line)}.empty{padding:20px;text-align:center;color:var(--muted);border:1px dashed #c9cac5;border-radius:9px;font-size:9px}.agent{display:grid;grid-template-rows:auto minmax(380px,1fr) auto;border:1px solid var(--line);border-radius:13px;overflow:hidden;background:#fff}.agenthead{padding:12px;border-bottom:1px solid var(--line)}.messages{padding:14px;background:#f8f7f3;display:flex;flex-direction:column;gap:8px;overflow:auto}.msg{max-width:78%;padding:9px 11px;border:1px solid var(--line);border-radius:11px;background:#fff;font-size:10px;white-space:pre-wrap}.msg.user{align-self:flex-end;background:var(--dark);border-color:var(--dark);color:#fff}.compose{padding:9px;display:grid;grid-template-columns:1fr auto;gap:6px;border-top:1px solid var(--line)}.modal{display:none;position:fixed;inset:0;z-index:50;background:rgba(0,0,0,.45);place-items:center;padding:18px}.modal.open{display:grid}.modalbox{width:min(540px,100%);background:#fff;border-radius:14px;padding:16px}.toast{display:none;position:fixed;right:16px;bottom:16px;z-index:60;padding:9px 12px;border-radius:8px;background:#171b1a;color:#fff;font-size:9px}@media(max-width:980px){.app{grid-template-columns:1fr}.side{position:static;height:auto}.nav{grid-template-columns:repeat(5,1fr)}.stats{grid-template-columns:repeat(2,1fr)}.cols{grid-template-columns:1fr}.catalog{grid-template-columns:1fr 1fr}}@media(max-width:620px){.nav{grid-template-columns:repeat(2,1fr)}.stats,.catalog,.form{grid-template-columns:1fr}.wide{grid-column:auto}.content{padding:14px}.cart{align-items:stretch;flex-direction:column}.hero h2{font-size:31px}}
</style></head><body><div class="app"><aside class="side"><div class="brand"><strong>Wholesale Portal</strong><small>Customer operations workspace</small></div><div class="acct"><small>Signed in for</small><b><?=app_escape((string)$account['business_name'])?></b></div><nav class="nav"><button class="active" data-page="overview">Overview</button><button data-page="catalog">Catalog</button><button data-page="orders">Orders</button><button data-page="invoices">Invoices</button><button data-page="quotes">Quotes</button><button data-page="requests">Requests</button><button data-page="history">History</button><button data-page="agent">AI Agent</button><button data-page="profile">Profile</button></nav></aside><main class="main"><header class="top"><div><h1 id="title">Wholesale Overview</h1><p id="subtitle">Orders, fulfillment, receivables, and next actions.</p></div><a href="logout.php">Sign out</a></header><div class="content">
<section class="page active" id="page-overview"><div class="hero"><div class="eyebrow">W5 customer workspace</div><h2>Buy, track, receive, and reconcile in one place.</h2><p class="muted">Your account-specific catalog, live fulfillment progress, invoices, balances, requests, and relationship history are connected to the same Wholesale account.</p></div><div class="stats"><div class="stat"><small>Account</small><strong id="sStatus">—</strong></div><div class="stat"><small>Open orders</small><strong id="sOrders">0</strong></div><div class="stat"><small>Receivables</small><strong id="sAR">$0</strong></div><div class="stat"><small>Overdue</small><strong id="sOverdue">$0</strong></div><div class="stat"><small>Catalog</small><strong id="sCatalog">0</strong></div></div><div class="cols"><section class="panel"><h3>Current orders</h3><p class="muted">Live allocation and delivery progress.</p><div class="list" id="overviewOrders"></div></section><aside class="panel"><h3>Next actions</h3><div class="list"><button class="btn primary" data-goto="catalog">Shop catalog</button><button class="btn" data-goto="invoices">Review invoices</button><button class="btn" data-request="sample">Request samples</button><button class="btn" data-goto="agent">Ask the account Agent</button></div></aside></div></section>
