<section class="page" id="page-profile"><div class="head"><div><div class="eyebrow">Customer profile</div><h2>Business preferences</h2></div></div><section class="panel"><form id="profileForm"><div class="form"><div><label>Phone</label><input class="field" id="pPhone"></div><div><label>Website</label><input class="field" id="pWebsite"></div><div><label>Billing email</label><input class="field" id="pBilling" type="email"></div><div><label>Preferred fulfillment</label><select class="field" id="pFulfillment"><option value="">Not set</option><option>Delivery</option><option>Pickup</option><option>Either</option></select></div><div class="wide"><label>Flavor preferences</label><textarea class="field" id="pFlavors" rows="3"></textarea></div><div class="wide"><label>Package preferences — comma separated</label><input class="field" id="pPackages"></div><div class="wide"><label>Customer notes</label><textarea class="field" id="pNotes" rows="3"></textarea></div><div class="wide"><label><input type="checkbox" id="pPrivate"> Interested in private label / custom program</label></div><div class="wide"><button class="btn primary" type="submit">Save profile</button></div></div></form></section><section class="panel" style="margin-top:10px"><h3>Locations</h3><div class="list" id="locations"></div></section></section>
